head.script:
scwin.trigger5_onclick = function(e) {
    textarea1.setValue(fusionchart1.getSVGString());
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 'getSVGString'버튼을 클릭한다.- Run the sample file and click the 'getSVGString' button.
    WebSquare.wUnit.addCommand("pause", "1500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger5').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 화면하단에 getSVGString값들이 보여진다.-The getSVGString values are shown at the bottom of the screen.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('textarea1').realValue != ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
